import {Studio} from './studio.js';
import {processes,moleculeTexts,sourceBase,colors,symbols} from './chemistry.js';
const $=id=>document.getElementById(id);
const state={mode:'element',id:'6',playing:false,p:0,token:0};let studio,elements,molecules,current,updateProcess;
const families=['#927ab0','#698ca9','#bd8b5f','#6b9a88','#ba7194','#b89450','#6d91a0','#8b8cbd','#829967','#a08098'];
const toast=text=>{$('toast').textContent=text;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,3500);};
async function getJSON(path){const r=await fetch(path);if(!r.ok)throw Error(`${path}: HTTP ${r.status}`);return r.json();}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const facts=rows=>$('facts').innerHTML=rows.map(([label,value,wide])=>`<div class="fact ${wide?'wide':''}"><small>${esc(label)}</small><b>${esc(value)}</b></div>`).join('');
function setPlaying(value){state.playing=value;$('play').textContent=value?'Ⅱ Pause':'▶ Abspielen';$('play').setAttribute('aria-pressed',value);}
function route(mode,id){const hash=`#${mode}/${id}`;if(location.hash===hash)select(mode,id);else location.hash=hash;}
function parseRoute(){const [mode,id]=location.hash.slice(1).split('/');const list=mode==='molecule'?molecules:mode==='process'?processes:elements;const valid=list.find(x=>String(x.id??x.z)===id);select(['element','molecule','process'].includes(mode)?mode:'element',valid?id:mode==='molecule'?'water':mode==='process'?'ionic':'6');}
function renderList(){const list=state.mode==='element'?elements:state.mode==='molecule'?molecules:processes;const q=$('search').value.toLocaleLowerCase('de');const category=state.mode==='element'?$('category').value:'';const filtered=list.filter(x=>`${x.name} ${x.symbol||''} ${x.z||''} ${x.formula||''}`.toLocaleLowerCase('de').includes(q)&&(!category||x.category===category));$('count').textContent=`${filtered.length} ${state.mode==='element'?'Elemente':state.mode==='molecule'?'Strukturen':'Abläufe'}`;
 $('items').replaceChildren(...filtered.map(x=>{const button=document.createElement('button');const id=String(x.id??x.z);button.className='item'+(id===state.id?' active':'');button.setAttribute('aria-pressed',String(id===state.id));button.innerHTML=`<span class="symbol">${esc(x.symbol|| (state.mode==='molecule'?'◈':'↝'))}</span><span><b>${esc(x.name)}</b><small>${esc(x.z?String(x.z).padStart(2,'0')+' · '+x.category:x.formula)}</small></span>`;button.onclick=()=>route(state.mode,id);return button;}));if(!filtered.length){const p=document.createElement('p');p.className='muted';p.textContent='Keine Treffer. Suche oder Filter ändern.';$('items').append(p);}
 document.querySelectorAll('.el').forEach(b=>{const hit=filtered.some(x=>String(x.z)===b.dataset.z);b.classList.toggle('dim',state.mode==='element'&&!hit);b.classList.toggle('active',state.mode==='element'&&b.dataset.z===state.id);b.setAttribute('aria-pressed',String(b.classList.contains('active')));});
}
function makePeriodic(){const categories=[...new Set(elements.map(e=>e.category))];categories.forEach(c=>$('category').add(new Option(c,c)));elements.forEach(el=>{const b=document.createElement('button');b.className='el';b.dataset.z=el.z;b.style.gridRow=el.row;b.style.gridColumn=el.col;b.style.setProperty('--family',families[categories.indexOf(el.category)%families.length]);b.innerHTML=`<small>${el.z}</small>${el.symbol}`;b.title=`${el.name} · ${el.category}`;b.setAttribute('aria-label',`${el.z} ${el.name}, ${el.symbol}`);b.onclick=()=>route('element',String(el.z));$('periodic').append(b);});}
function noteKey(){return 'elementa:note:'+state.mode+':'+state.id;}
function loadNote(){try{$('note').value=localStorage.getItem(noteKey())||'';$('note-status').textContent='';}catch{$('note').value='';$('note-status').textContent='Lokaler Speicher ist nicht verfügbar.';}}
function setLegend(entries){$('legend').innerHTML=entries.map(([color,label])=>`<span><i style="background:${color}"></i>${esc(label)}</span>`).join('');}
function setAngular(){const [n,l]= $('orbital').value.split(',').map(Number);const options=l===0?[[0,'s']]:l===1?[[0,'pᵧ'],[1,'pₓ'],[-1,'p𝓏']]:l===2?[[0,'d: 3y² − r²'],[1,'d: xy'],[-1,'d: yz'],[2,'d: x² − z²'],[-2,'d: xz']]:[[0,'f-Basis: m = 0'],[1,'f-Basis: m = +1'],[-1,'f-Basis: m = −1'],[2,'f-Basis: m = +2'],[-2,'f-Basis: m = −2'],[3,'f-Basis: m = +3'],[-3,'f-Basis: m = −3']];$('angular').replaceChildren(...options.map(([v,t])=>new Option(t,v)));}
function drawAtom(){const el=current;if(state.mode!=='element'||!el)return;const orbital=$('model').value==='orbital';$('orbital-wrap').hidden=$('angular-wrap').hidden=!orbital;let [n,l]=$('orbital').value.split(',').map(Number);studio?.atom(el,$('model').value,n,l,Number($('angular').value));$('model-note').textContent=orbital?'Einzelorbital · wasserstoffartige Form, keine Gesamtladungsdichte':'Schalenmodell · Bahnen und Kern symbolisch, nicht maßstabsgetreu';setLegend(orbital?[['#249d98','ψ positiv'],['#b28be0','ψ negativ']]:[['#238878','Elektronen'],['#ddad7c','Kern symbolisch']]);}
async function select(mode,id){const changedMode=state.mode!==mode;const token=++state.token;state.mode=mode;state.id=String(id);state.p=0;setPlaying(false);updateProcess=null;if(studio)studio.tick=()=>{};$('picked').hidden=true;if(studio)$('loading').hidden=true;if(changedMode){$('search').value='';$('category').value='';}const isAtom=mode==='element',isMolecule=mode==='molecule';document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode));});$('explorer-title').textContent=isAtom?'Elemente':isMolecule?'Moleküle':'Abläufe';$('explorer-desc').textContent=isAtom?'Vom Atom zum großen Ganzen.':isMolecule?'Echte Daten. Räumlich entdecken.':'Chemie Schritt für Schritt.';$('search').placeholder=isAtom?'Name, Symbol oder Ordnungszahl':'Eintrag suchen';$('filter-wrap').hidden=!isAtom;$('periodic-panel').hidden=!isAtom;$('representation').hidden=!isAtom;$('molecule-tools').hidden=!isMolecule;$('process-controls').hidden=isAtom||isMolecule;$('scene-type').textContent=isAtom?'ATOM-STUDIO':isMolecule?'STRUKTUR-STUDIO':'PROZESS-STUDIO';renderList();loadNote();
 if(isAtom){current=elements.find(e=>String(e.z)===state.id);const e=current;$('scene-title').textContent=e.name;$('hero-symbol').textContent=e.symbol;$('scene-subtitle').textContent=`${String(e.z).padStart(2,'0')} / ${e.symbol} / ${e.category}`;$('knowledge-title').textContent='Ein Element. Seine Struktur.';facts([['Ordnungszahl',e.z],['Atommasse / u',e.mass],['Elektronegativität',e.en],['Standardzustand',e.state],['Elektronenkonfiguration',e.config,true],['Schalenbelegung',e.shells.join(' · '),true]]);$('orbital').replaceChildren(...e.orbitals.map(([n,l,c])=>new Option(`${n}${l} · ${c} Elektron${c===1?'':'en'}`,`${n},${'spdf'.indexOf(l)}`)));$('orbital').selectedIndex=e.orbitals.length-1;setAngular();$('explanation').innerHTML=`<h3>Was macht ${esc(e.name)} aus?</h3><p>Die Ordnungszahl ${e.z} gibt die Protonenzahl an. Ein neutrales ${esc(e.name)}atom besitzt ebenso viele Elektronen. Die Atommasse ist keine Neutronenzahl; für die Neutronenzahl braucht man ein bestimmtes Isotop.</p><h3>Zwei Modelle, zwei Blickwinkel</h3><p>Das Schalenmodell ordnet Elektronen nach Hauptenergieniveaus. Gezeichnete Bahnen sind eine Merkhilfe. Im Orbitalmodell beschreibt |ψ|² die räumliche Aufenthaltswahrscheinlichkeit.</p><div class="callout">Wähle eine besetzte Unterschale und eine Orbitalform. Ein Orbital kann höchstens zwei Elektronen aufnehmen. Die Punktwolke zeigt mögliche Aufenthaltsorte, nicht Tausende Elektronen.</div><p>s, p, d und f enthalten 1, 3, 5 und 7 Orbitale. Die angezeigte Konfiguration stammt aus PubChem; besonders bei schweren Elementen können Angaben theoretisch vorhergesagt sein.</p>`;$('source-link').href='https://github.com/openstax/osbooks-chemistry-bundle/blob/9928441ef0badc3ff024c6a1fe2842c0048ea858/modules/m68734/index.cnxml';drawAtom();
 }else if(isMolecule){const meta=molecules.find(x=>x.id===id);current=null;$('scene-title').textContent=meta.name;$('hero-symbol').textContent='';$('scene-subtitle').textContent=`${meta.formula} / PubChem CID ${meta.cid}`;$('knowledge-title').textContent=moleculeTexts[id][0];facts([['Formel',meta.formula],['PubChem CID',meta.cid]]);$('explanation').innerHTML=`<h3>Struktur verstehen</h3><p>${moleculeTexts[id][1]}</p><div class="callout">${id==='salt'?'Ein Ionengitter, kein isoliertes NaCl-Molekül. Stäbe dienen der Orientierung und sind keine Elektronenpaarbindungen.':'Ein vorberechnetes PubChem-Konformer. Moleküle sind beweglich; das Modell zeigt eine ausgewählte Geometrie.'}</div><p>Tippe eine Atomkugel an, um das Element zu sehen. Farben kennzeichnen Elementsorten; die Kalottenansicht nutzt angenäherte Van-der-Waals-Radien.</p>`;$('source-link').href=`https://pubchem.ncbi.nlm.nih.gov/compound/${meta.cid}`;$('model-note').textContent=id==='salt'?'Schematischer Ionenkristall · 64 Ionen · Verhältnis 1:1':'PubChem 3D-Konformer · Bindungsordnung aus dem Datensatz';$('molecule-tools').hidden=id==='salt';studio?.clear();$('loading').textContent='Struktur wird geladen …';$('loading').hidden=false;try{const data=await getJSON(`data/${id}.json`);if(token!==state.token)return;current=data;facts([['Formel',meta.formula],['PubChem CID',meta.cid],['Atome im Modell',id==='salt'?'64 Ionen':data.atoms.length],['Geometrie',id==='salt'?'Ionengitter':'3D-Konformer']]);studio?.molecule(data,$('mol-style').value,$('hydrogen').checked);setLegend([...new Set(data.atoms.map(a=>a.element))].map(z=>[colors[z],symbols[z]]));$('loading').hidden=!!studio;}catch(e){if(token!==state.token)return;$('loading').textContent='Struktur konnte nicht geladen werden. Bitte Seite neu laden.';console.error(e);}
 }else{current=processes.find(x=>x.id===id);$('scene-title').textContent=current.name;$('scene-subtitle').textContent=current.formula;$('hero-symbol').textContent='';$('knowledge-title').textContent='Veränderung sichtbar machen.';facts([['Schritte',4],['Modell','Schematisch']]);$('source-link').href='https://github.com/openstax/osbooks-chemistry-bundle/blob/9928441ef0badc3ff024c6a1fe2842c0048ea858/modules/'+({ionic:'m68737',covalent:'m68738',dissolve:'m68778'}[id])+'/index.cnxml';$('model-note').textContent='Didaktische Animation · keine Reaktionssimulation';$('steps').replaceChildren(...current.steps.map((text,i)=>{const b=document.createElement('button');b.textContent=`${i+1}. ${text}`;b.onclick=()=>{state.p=(i+.15)/4;showProgress();};return b;}));updateProcess=studio?.process(id);if(studio)studio.tick=(t,dt)=>{if(!state.playing)return;state.p=Math.min(1,state.p+dt*Number($('speed').value)/20);showProgress();if(state.p===1)setPlaying(false);};setLegend(id==='covalent'?[['#298d90','Elektronen'],['#ccad7a','Protonen']]:[['#ae80db','Na⁺'],['#76b779','Cl⁻'],['#e9655e','Sauerstoff'],['#e5eaef','Wasserstoff']]);showProgress();}
}
function showProgress(){updateProcess?.(state.p);$('timeline').value=Math.round(state.p*1000);$('progress').textContent=Math.round(state.p*100)+' %';let i=Math.min(3,Math.floor(state.p*4));$('steps').querySelectorAll('button').forEach((b,k)=>{b.classList.toggle('active',k===i);b.setAttribute('aria-pressed',String(k===i));});$('explanation').innerHTML=`<h3>${i+1} / ${current.steps[i]}</h3><p>${current.texts[i]}</p><div class="callout">${current.formula}</div><p>Zeitleiste ziehen oder einen Schritt wählen. Abspielen zeigt den Übergang; das Tempo lässt sich ändern.</p>`;}
try{
 [elements,molecules]=await Promise.all([getJSON('data/elements.json'),getJSON('data/molecules.json')]);makePeriodic();
 try{studio=new Studio($('viewport'),text=>{$('picked').textContent=text;$('picked').hidden=!text;});$('loading').hidden=true;}catch(e){$('loading').textContent='3D nicht verfügbar. WebGL2 aktivieren oder einen aktuellen Browser verwenden. Lerntexte und Periodensystem bleiben nutzbar.';console.error(e);}
 document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>route(b.dataset.mode,b.dataset.mode==='element'?'6':b.dataset.mode==='molecule'?'water':'ionic'));
 $('search').oninput=renderList;$('category').onchange=renderList;$('model').onchange=drawAtom;$('orbital').onchange=()=>{setAngular();drawAtom();};$('angular').onchange=drawAtom;
 $('mol-style').onchange=$('hydrogen').onchange=()=>{if(current&&state.mode==='molecule')studio?.molecule(current,$('mol-style').value,$('hydrogen').checked);};
 $('reset').onclick=()=>studio?.reset();$('rotate').onclick=()=>{if(!studio)return;studio.controls.autoRotate=!studio.controls.autoRotate;$('rotate').setAttribute('aria-pressed',studio.controls.autoRotate);};$('theme').onclick=()=>{const dark=document.querySelector('.studio').classList.toggle('dark');$('theme').setAttribute('aria-pressed',dark);$('theme').textContent=dark?'Helles Studio':'Dunkles Studio';};$('export').onclick=()=>{if(studio)studio.export($('scene-title').textContent);else toast('PNG-Export benötigt ein verfügbares 3D-Studio.');};
 $('timeline').oninput=()=>{state.p=Number($('timeline').value)/1000;showProgress();};$('play').onclick=()=>{if(state.p>=1)state.p=0;setPlaying(!state.playing);showProgress();};
 $('note').oninput=()=>{try{localStorage.setItem(noteKey(),$('note').value);$('note-status').textContent='Gespeichert.';}catch{$('note-status').textContent='Speichern nicht möglich: Browser-Speicher gesperrt oder voll.';}};
 $('sources-open').onclick=()=>$('sources').showModal();$('sources-close').onclick=()=>$('sources').close();window.addEventListener('hashchange',parseRoute);
 document.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||$('sources').open)return;if(e.code==='Space'&&state.mode==='process'){e.preventDefault();$('play').click();}if(e.key==='r')studio?.reset();});parseRoute();
}catch(e){$('loading').textContent='App-Daten konnten nicht geladen werden. Bitte über HTTP starten (python start.py), nicht per Datei-Doppelklick.';console.error(e);}
